// Some portions generated by Claude
package org.eclipse.rdf4j.workbench.commands;

import java.util.Comparator;
import java.util.Locale;
import java.util.Optional;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.function.Predicate;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.workbench.util.TupleResultBuilder;
import org.eclipse.rdf4j.workbench.util.WorkbenchRequest;

/**
 * Shared behavior of the Types and Graphs pages: values in name order, a case-insensitive substring filter, and counts
 * that are requested separately and abandoned after a time budget. A count runs on its own connection, so that an
 * abandoned count never keeps the page's connection (and with it the response) open.
 */
final class BrowseList {

	static final String FILTER = "filter";

	static final String COUNTS = "counts";

	static final String COUNTS_TIMED_OUT = "counts-timed-out";

	/** The same budget the Summary page gives the repository size. */
	static final long COUNT_BUDGET_MILLIS = 2000;

	static final int COUNT_BUDGET_SECONDS = (int) TimeUnit.MILLISECONDS.toSeconds(COUNT_BUDGET_MILLIS);

	static final Comparator<Value> BY_NAME = Comparator.comparing(Value::stringValue);

	private final ExecutorService executor = Executors.newCachedThreadPool(runnable -> {
		Thread thread = new Thread(runnable, "rdf4j-workbench-counts");
		thread.setDaemon(true);
		return thread;
	});

	static boolean countsRequested(WorkbenchRequest req) {
		return "true".equals(req.getParameter(COUNTS));
	}

	/** The filter text as typed, trimmed; empty when there is none. */
	static String filter(WorkbenchRequest req) {
		String value = req.getParameter(FILTER);
		return value == null ? "" : value.trim();
	}

	static Predicate<Value> matching(String filter) {
		if (filter.isEmpty()) {
			return value -> true;
		}
		String needle = filter.toLowerCase(Locale.ROOT);
		return value -> value.stringValue().toLowerCase(Locale.ROOT).contains(needle);
	}

	/** Repeats a non-empty filter in the page metadata, so the page can show it in its filter field. */
	static void echoFilter(TupleResultBuilder builder, String filter) {
		if (!filter.isEmpty()) {
			builder.metadata(FILTER, filter);
		}
	}

	/** Writes the answer for counts that did not finish within the budget: no rows. */
	static void countsTimedOut(TupleResultBuilder builder) {
		builder.metadata(COUNTS_TIMED_OUT, true);
	}

	/**
	 * Runs a count and waits at most {@link #COUNT_BUDGET_MILLIS}.
	 *
	 * @return the count, or empty when it took longer; the count is then cancelled
	 */
	<T> Optional<T> withinBudget(Callable<T> count) throws Exception {
		Future<T> future = executor.submit(count);
		try {
			return Optional.of(future.get(COUNT_BUDGET_MILLIS, TimeUnit.MILLISECONDS));
		} catch (TimeoutException e) {
			future.cancel(true);
			return Optional.empty();
		} catch (ExecutionException e) {
			Throwable cause = e.getCause();
			if (cause instanceof Exception exception) {
				throw exception;
			}
			throw e;
		}
	}

	void shutdown() {
		executor.shutdownNow();
	}
}
